package org.apache.commons.compress.archivers.tar;

import java.io.*;
import java.math.*;
import java.util.*;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;

public class TarUtils_parseOctal_TriageGen1Test {







    @Test
    public void testParseOctal_WithTrailingSpaceAfterPadding() {
        // Testing the 'if (currentByte == (byte) ' ') break;' inside the padding check
        // This occurs if a space is encountered after the first non-zero/non-space digit is processed
        // Wait, the logic says: if (stillPadding) continue; if (currentByte == ' ') break;
        // To hit the break, stillPadding must be false.
        byte[] buffer = "00012 34".getBytes();
        assertEquals(10L, TarUtils.parseOctal(buffer, 0, buffer.length));
    }












}

